RestServiceDefinition.SqlExecute:
WITH RoleWithIds AS ( --Roles for this Business Role, including existing SELECT -- br.SystemDescription, systems.id AS application_id, br.rolename, case when er.approles_id is null then --create a guid using hex and randomblob lower( hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-' || '4' || substr(hex(randomblob(2)), 2) || '-' || substr('AB89', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6))
) else er.approles_id end AS row_id FROM businessrole AS br LEFT OUTER JOIN systems ON systems.displayName = br.SystemDescription left outer join existingAppRoles er on er.id = systems.id and er.approles_displayName = br.rolename -- Roles for other Business Roles for this app UNION SELECT e.id, e.approles_displayname, e.approles_id AS row_id FROM existingAppRoles e WHERE e.approles_displayname NOT IN ( SELECT b.rolename FROM businessrole b WHERE e.displayName = b.SystemDescription )
) SELECT application_id, json_group_array( json_object( 'id', row_id, 'allowedMemberTypes', json('["User"]'), 'description', rolename, 'displayName', rolename, 'value', replace(rolename,' ','')
) ) AS role_info FROM RoleWithIds GROUP BY application_id;
